export const AVATAR_CSS = "/* ============================================================================\n   Matic bust avatar — stylesheet\n   BUST AVATAR SPECIFICATION v7 · 2026.09.09\n\n   Pairs with matic-avatar.svg (one chassis, swappable regions) and\n   matic-avatar.manifest.json (the state map — this file must agree with it).\n\n   Selectors\n   ---------\n   CSS targets CLASSES (.mav, .mav-eyes, .mav-mouth, .mav-rig ...), not ids, so\n   many avatars can coexist on one page. The ids in the SVG are kept for\n   single-instance addressability as the spec asks; if you instantiate more\n   than one, namespace or drop the ids and rely on the classes. Duplicate\n   clipPath ids are harmless here because every instance has identical\n   geometry, but namespace them too if that ever stops being true.\n\n   Contract\n   --------\n   Set ONE attribute to change state:      svg.mav[data-state=\"...\"]\n   The rules below derive everything else: eye shape, mouth shape, gaze shift,\n   the three state colours, which accessories show, and which rig motion runs.\n\n   During speech, override the mouth directly at phoneme rate:\n       .mav-mouth[data-shape=\"narrow\"]   etc.\n   ...and set data-visemes on the svg so the fallback chatter stops.\n\n   Performance\n   -----------\n   Integrated graphics, no discrete GPU. Everything animated here is transform\n   or opacity on a small number of nodes. No filters, no 3D transforms, no\n   will-change, nothing that forces a compositing layer.\n   ========================================================================= */\n\n/* ---------------------------------------------------------------- tokens  */\n\n.mav,\n.matic-avatar-theme-light {\n  --matic-avatar-field: #cbe3f7;\n  --matic-avatar-shell: #fdfefe;\n  --matic-avatar-shell-shade: #d9e0e7;\n  --matic-avatar-ink: #1b3556;\n  --matic-avatar-pod: #3f7fc4;\n  --matic-avatar-pod-inner: #5c9ad9;\n  --matic-avatar-collar: #1f5fa8;\n  --matic-avatar-badge-ink: #fdfefe;\n  --matic-avatar-paper: #f2f2f3;\n  --matic-avatar-paper-line: #5980a6;\n  --matic-avatar-paper-line-dim: #b7b7ba;\n  --matic-avatar-paper-edge: #416180;\n  --matic-avatar-accent-scan: #7cd8f5;\n\n  --matic-avatar-eye-default: #bfe4f7;\n  --matic-avatar-tip-default: #3f7fc4;\n  --matic-avatar-mark-default: #1f5fa8;\n\n  --matic-avatar-eye-thinking: #c3adff;\n  --matic-avatar-tip-thinking: #a78bfa;\n  --matic-avatar-mark-thinking: #7c5cd6;\n\n  --matic-avatar-eye-success: #8df0bb;\n  --matic-avatar-tip-success: #6ee7a8;\n  --matic-avatar-mark-success: #3f8f5e;\n\n  --matic-avatar-eye-apologising: #b8cfe0;\n  --matic-avatar-tip-apologising: #8fa9bd;\n  --matic-avatar-mark-apologising: #6d8598;\n\n  --matic-avatar-eye-declining: #7fe0d8;\n  --matic-avatar-tip-declining: #2fb3ab;\n  --matic-avatar-mark-declining: #1f7a74;\n\n  --matic-avatar-eye-escalating: #f7d69e;\n  --matic-avatar-tip-escalating: #f0c27a;\n  --matic-avatar-mark-escalating: #b07b2e;\n\n  --matic-avatar-eye-error: #f7aba3;\n  --matic-avatar-tip-error: #f08a80;\n  --matic-avatar-mark-error: #b1554c;\n\n  /* Resolved per state by the [data-state] rules below. */\n  --matic-avatar-eye: var(--matic-avatar-eye-default);\n  --matic-avatar-tip: var(--matic-avatar-tip-default);\n  --matic-avatar-mark: var(--matic-avatar-mark-default);\n}\n\n/* Dark panel: v7 §05 knocks the field out entirely. A token swap on the same\n   markup — not a second asset. State colours are deliberately unchanged, so a\n   state means the same thing in either theme. */\n.matic-avatar-theme-dark {\n  --matic-avatar-field: transparent;\n  --matic-avatar-shell: #e8edf2;\n  --matic-avatar-shell-shade: #c2ccd6;\n  --matic-avatar-paper: #e8e8ea;\n  --matic-avatar-badge-ink: #12213a;\n}\n\n/* ------------------------------------------------------- region switching */\n/* All shapes live in the markup. Exactly one is shown. `display` is used\n   rather than opacity so hidden shapes cost nothing to paint. */\n\n.mav .eye-shape,\n.mav .mouth-shape { display: none; }\n\n.mav-eyes[data-shape=\"oval\"]    > .eye-shape[data-shape=\"oval\"],\n.mav-eyes[data-shape=\"round\"]   > .eye-shape[data-shape=\"round\"],\n.mav-eyes[data-shape=\"happy\"]   > .eye-shape[data-shape=\"happy\"],\n.mav-eyes[data-shape=\"lowered\"] > .eye-shape[data-shape=\"lowered\"],\n.mav-eyes[data-shape=\"cross\"]   > .eye-shape[data-shape=\"cross\"] { display: block; }\n\n.mav-mouth[data-shape=\"smile\"]      > .mouth-shape[data-shape=\"smile\"],\n.mav-mouth[data-shape=\"grin\"]       > .mouth-shape[data-shape=\"grin\"],\n.mav-mouth[data-shape=\"talk\"]       > .mouth-shape[data-shape=\"talk\"],\n.mav-mouth[data-shape=\"closed\"]     > .mouth-shape[data-shape=\"closed\"],\n.mav-mouth[data-shape=\"narrow\"]     > .mouth-shape[data-shape=\"narrow\"],\n.mav-mouth[data-shape=\"wideFlat\"]   > .mouth-shape[data-shape=\"wideFlat\"],\n.mav-mouth[data-shape=\"roundSmall\"] > .mouth-shape[data-shape=\"roundSmall\"],\n.mav-mouth[data-shape=\"roundLarge\"] > .mouth-shape[data-shape=\"roundLarge\"],\n.mav-mouth[data-shape=\"open\"]       > .mouth-shape[data-shape=\"open\"] { display: block; }\n\n/* No transition on the mouth, ever. At phoneme rate a transition either lags\n   the audio or is cut off mid-interpolation, which reads as a wobble. */\n.mav-mouth, .mav-mouth * { transition: none !important; }\n\n/* Accessories: hidden by default, shown per state. */\n.mav-badge, .mav-dots, .mav-rings, .mav-ticket,\n.mav-aperture, .mav-slot, .mav-doc, .mav-scan { display: none; }\n\n/* --------------------------------------------------------- state colours  */\n\n.mav[data-state=\"thinking\"] {\n  --matic-avatar-eye: var(--matic-avatar-eye-thinking);\n  --matic-avatar-tip: var(--matic-avatar-tip-thinking);\n  --matic-avatar-mark: var(--matic-avatar-mark-thinking);\n}\n.mav[data-state=\"success\"] {\n  --matic-avatar-eye: var(--matic-avatar-eye-success);\n  --matic-avatar-tip: var(--matic-avatar-tip-success);\n  --matic-avatar-mark: var(--matic-avatar-mark-success);\n}\n.mav[data-state=\"apologising\"] {\n  --matic-avatar-eye: var(--matic-avatar-eye-apologising);\n  --matic-avatar-tip: var(--matic-avatar-tip-apologising);\n  --matic-avatar-mark: var(--matic-avatar-mark-apologising);\n}\n.mav[data-state=\"declining\"] {\n  --matic-avatar-eye: var(--matic-avatar-eye-declining);\n  --matic-avatar-tip: var(--matic-avatar-tip-declining);\n  --matic-avatar-mark: var(--matic-avatar-mark-declining);\n}\n.mav[data-state=\"escalating\"] {\n  --matic-avatar-eye: var(--matic-avatar-eye-escalating);\n  --matic-avatar-tip: var(--matic-avatar-tip-escalating);\n  --matic-avatar-mark: var(--matic-avatar-mark-escalating);\n}\n.mav[data-state=\"error\"] {\n  --matic-avatar-eye: var(--matic-avatar-eye-error);\n  --matic-avatar-tip: var(--matic-avatar-tip-error);\n  --matic-avatar-mark: var(--matic-avatar-mark-error);\n}\n\n/* Eye and mouth shape per state, so [data-state] alone is sufficient — the\n   pairings here are the manifest's pairings and must not drift from it.\n\n   The :not([data-shape]) guard is what makes the speech path work: set\n   data-shape on #mouth and it wins outright, with no specificity fight and no\n   need to clear data-state. Remove data-shape and the state's mouth returns. */\n\n.mav[data-state=\"idle\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"oval\"],\n.mav[data-state=\"idle\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"smile\"] { display: block; }\n.mav[data-state=\"listening\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"round\"],\n.mav[data-state=\"listening\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"roundSmall\"] { display: block; }\n.mav[data-state=\"thinking\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"oval\"],\n.mav[data-state=\"thinking\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"narrow\"] { display: block; }\n.mav[data-state=\"speaking\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"oval\"],\n.mav[data-state=\"speaking\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"talk\"] { display: block; }\n.mav[data-state=\"greeting\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"oval\"],\n.mav[data-state=\"greeting\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"grin\"] { display: block; }\n.mav[data-state=\"success\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"happy\"],\n.mav[data-state=\"success\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"grin\"] { display: block; }\n.mav[data-state=\"apologising\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"lowered\"],\n.mav[data-state=\"apologising\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"narrow\"] { display: block; }\n.mav[data-state=\"declining\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"round\"],\n.mav[data-state=\"declining\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"narrow\"] { display: block; }\n.mav[data-state=\"escalating\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"oval\"],\n.mav[data-state=\"escalating\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"narrow\"] { display: block; }\n.mav[data-state=\"error\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"cross\"],\n.mav[data-state=\"error\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"wideFlat\"] { display: block; }\n.mav[data-state=\"accept\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"round\"],\n.mav[data-state=\"accept\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"roundSmall\"] { display: block; }\n.mav[data-state=\"ingest\"] .mav-eyes:not([data-shape])  > .eye-shape[data-shape=\"oval\"],\n.mav[data-state=\"ingest\"] .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"narrow\"] { display: block; }\n\n/* ------------------------------------------------- per-state composition  */\n/* Gaze shift, accessories and rig motion. Shapes are set in the block above. */\n\n.mav[data-state] .mav-eyes { transform: translate(0, 0); }\n\n.mav[data-state=\"idle\"]        .mav-rig { animation: matic-breathe var(--matic-breathe-duration, 4.4s) ease-in-out var(--matic-phase, 0s) infinite; }\n.mav[data-state=\"thinking\"]    .mav-rig { animation: matic-breathe var(--matic-breathe-duration, 4.4s) ease-in-out var(--matic-phase, 0s) infinite; }\n.mav[data-state=\"speaking\"]    .mav-rig { animation: matic-breathe var(--matic-breathe-duration, 4.4s) ease-in-out var(--matic-phase, 0s) infinite; }\n.mav[data-state=\"success\"]     .mav-rig { animation: matic-breathe var(--matic-breathe-duration, 4.4s) ease-in-out var(--matic-phase, 0s) infinite; }\n.mav[data-state=\"declining\"]   .mav-rig { animation: matic-breathe var(--matic-breathe-duration, 4.4s) ease-in-out var(--matic-phase, 0s) infinite; }\n.mav[data-state=\"escalating\"]  .mav-rig { animation: matic-breathe var(--matic-breathe-duration, 4.4s) ease-in-out var(--matic-phase, 0s) infinite; }\n.mav[data-state=\"accept\"]      .mav-rig { animation: matic-breathe var(--matic-breathe-duration, 4.4s) ease-in-out var(--matic-phase, 0s) infinite; }\n.mav[data-state=\"ingest\"]      .mav-rig { animation: matic-breathe var(--matic-breathe-duration, 4.4s) ease-in-out var(--matic-phase, 0s) infinite; }\n\n/* A two-beat that RESOLVES, then the client falls the state back to idle.\n   Not looped: a looping nod makes the panel fidget while the user reads. */\n.mav[data-state=\"greeting\"]  .mav-rig { animation: matic-nod 1.5s ease-in-out 2 both; }\n.mav[data-state=\"listening\"] .mav-rig { animation: matic-tilt 3s ease-in-out infinite; }\n.mav[data-state=\"apologising\"] .mav-rig { animation: matic-bow 3.4s ease-in-out infinite; }\n/* error holds still — stillness is part of how it reads. */\n.mav[data-state=\"error\"] .mav-rig { animation: none; }\n\n.mav[data-state=\"thinking\"] .mav-eyes { transform: translate(-3px, -2px); }\n.mav[data-state=\"apologising\"] .mav-eyes { transform: translate(0, 3px); }\n.mav[data-state=\"ingest\"] .mav-eyes { transform: translate(0, 1px); }\n\n.mav .mav-tip { animation: matic-pulse 2.6s ease-in-out var(--matic-phase, 0s) infinite; }\n.mav[data-state=\"ingest\"] .mav-tip { animation: matic-flash 0.4s steps(1, end) infinite; }\n\n.mav[data-state=\"speaking\"]:not([data-visemes]) .mav-talk {\n  animation: matic-talk 0.42s ease-in-out infinite;\n  transform-box: fill-box;\n  transform-origin: 50% 50%;\n}\n/* With a viseme stream bound, the fallback chatter must be off. */\n.mav[data-visemes] .mav-talk { animation: none; }\n\n.mav[data-state=\"success\"]     .mav-badge,\n.mav[data-state=\"declining\"]   .mav-badge,\n.mav[data-state=\"escalating\"]  .mav-badge,\n.mav[data-state=\"error\"]       .mav-badge { display: block; }\n\n/* The badge disc is shared; the glyph inside is not. All four live in the same\n   coordinate space and exactly one is shown — a swap, never a re-render. */\n.mav-badge-glyph { display: none; }\n.mav[data-state=\"success\"]    .mav-badge-glyph[data-glyph=\"tick\"],\n.mav[data-state=\"declining\"]  .mav-badge-glyph[data-glyph=\"question\"],\n.mav[data-state=\"escalating\"] .mav-badge-glyph[data-glyph=\"arrow\"],\n.mav[data-state=\"error\"]      .mav-badge-glyph[data-glyph=\"bang\"] { display: block; }\n\n.mav[data-state=\"thinking\"]   .mav-dots { display: block; }\n.mav[data-state=\"listening\"]  .mav-rings { display: block; }\n.mav[data-state=\"escalating\"] .mav-ticket { display: block; }\n.mav[data-state=\"accept\"]     .mav-aperture,\n.mav[data-state=\"accept\"]     .mav-slot { display: block; }\n.mav[data-state=\"ingest\"]     .mav-doc,\n.mav[data-state=\"ingest\"]     .mav-scan { display: block; }\n\n/* accept: the mark dims as the aperture opens over it. */\n.mav[data-state=\"accept\"] .mav-mark { opacity: 0.2; }\n\n.mav .mav-dots .acc-dot { animation: matic-dot 1.1s ease-in-out infinite; transform-box: fill-box; transform-origin: 50% 50%; }\n.mav .mav-dots .acc-dot:nth-child(2) { animation-delay: 0.15s; }\n.mav .mav-dots .acc-dot:nth-child(3) { animation-delay: 0.3s; }\n\n.mav .mav-rings ellipse { animation: matic-ring 1.6s ease-out infinite; transform-box: fill-box; transform-origin: 50% 50%; }\n.mav .mav-rings ellipse:nth-child(2) { animation-delay: 0.4s; }\n\n.mav .mav-aperture { animation: matic-aperture 1.5s ease-out infinite; transform-box: fill-box; transform-origin: 50% 50%; }\n.mav .mav-doc { animation: matic-ingest 1.6s ease-in infinite; transform-box: fill-box; transform-origin: 50% 50%; }\n.mav .mav-scan { animation: matic-scan 1.4s linear infinite; }\n\n/* --------------------------------------------------------------- motion   */\n/* Values are the manifest's motion{} block. Keep the two in step. */\n\n@keyframes matic-breathe {\n  0%, 100% { transform: translateY(0); }\n  50%      { transform: translateY(-2.5px); }\n}\n@keyframes matic-nod {\n  0%   { transform: translateY(0) rotate(0deg); }\n  30%  { transform: translateY(-4px) rotate(-3deg); }\n  60%  { transform: translateY(1px) rotate(2deg); }\n  100% { transform: translateY(0) rotate(0deg); }\n}\n@keyframes matic-tilt {\n  0%, 100% { transform: rotate(0deg); }\n  50%      { transform: rotate(-4deg); }\n}\n@keyframes matic-bow {\n  0%, 100%  { transform: translateY(0) rotate(0deg); }\n  35%, 65%  { transform: translateY(6px) rotate(3deg); }\n}\n@keyframes matic-talk {\n  0%, 100% { transform: scaleY(0.35); }\n  50%      { transform: scaleY(1.5); }\n}\n@keyframes matic-pulse {\n  0%, 100% { opacity: 0.55; }\n  50%      { opacity: 1; }\n}\n@keyframes matic-flash {\n  0%, 49%   { opacity: 1; }\n  50%, 100% { opacity: 0.14; }\n}\n@keyframes matic-dot {\n  0%, 100% { opacity: 0.18; transform: translateY(0); }\n  40%      { opacity: 1; transform: translateY(-5px); }\n}\n@keyframes matic-ring {\n  0%   { transform: scale(0.55); opacity: 0.85; }\n  100% { transform: scale(2.1); opacity: 0; }\n}\n@keyframes matic-aperture {\n  0%   { transform: scale(0.75); opacity: 0.9; }\n  100% { transform: scale(1.6); opacity: 0; }\n}\n@keyframes matic-ingest {\n  0%   { transform: translateY(-40px) scale(1); opacity: 0; }\n  18%  { opacity: 1; }\n  78%  { transform: translateY(-2px) scale(0.42); opacity: 1; }\n  100% { transform: translateY(2px) scale(0.1); opacity: 0; }\n}\n@keyframes matic-scan {\n  0%   { transform: translateY(0); opacity: 0; }\n  22%  { opacity: 0.85; }\n  100% { transform: translateY(54px); opacity: 0; }\n}\n\n/* Idle jitter. Set these two properties per mount, ONCE, and keep them stable\n   for the mount's lifetime:\n       el.style.setProperty('--matic-breathe-duration', (4.4 * (0.95 + Math.random() * 0.1)).toFixed(2) + 's');\n       el.style.setProperty('--matic-phase', '-' + (Math.random() * 5).toFixed(2) + 's');\n   Without them, two avatars on screen breathe in lockstep — an obvious tell\n   that they are one asset rather than two agents. Do not recompute on render. */\n\n/* ------------------------------------------------------------- tray dot   */\n/* 16–24px. Four reads, separated by MOTION first: at this size on an unknown\n   taskbar background, assume hue is unreadable. */\n\n.tray-dot {\n  position: relative;\n  display: inline-block;\n  width: var(--tray-size, 16px);\n  height: var(--tray-size, 16px);\n  border-radius: 50%;\n  background: var(--tray-colour, #3f7fc4);\n}\n.tray-dot::after { content: \"\"; position: absolute; inset: 0; border-radius: 50%; }\n\n.tray-dot[data-read=\"resting\"] { animation: matic-pulse 2.6s ease-in-out infinite; }\n.tray-dot[data-read=\"working\"] { animation: matic-pulse 1s ease-in-out infinite; }\n.tray-dot[data-read=\"needsYou\"]::after {\n  border: 1.5px solid var(--tray-colour, #3f7fc4);\n  animation: matic-tray-ring 1.6s ease-out infinite;\n}\n/* unavailable: static. Absence of motion is the signal — a statement that the\n   assistant cannot work, not a request. */\n.tray-dot[data-read=\"unavailable\"] { animation: none; }\n/* 'none' states never reach the tray; the tray returns to resting. */\n\n@keyframes matic-tray-ring {\n  0%   { transform: scale(0.8); opacity: 0.9; }\n  100% { transform: scale(2.2); opacity: 0; }\n}\n\n/* Light system themes: keep the hue, add separation. */\n.matic-tray-light .tray-dot { box-shadow: 0 0 0 1px rgba(29, 31, 32, 0.2); }\n\n/* ------------------------------------------------- prefers-reduced-motion */\n/* NOT in v7 — a design decision made for this delivery.\n\n   The structural problem: v7 makes motion the primary tray channel precisely\n   because hue is unreadable at 16px. Switch motion off and the four tray reads\n   collapse into one dot. Turning animation off is therefore not sufficient;\n   the tray needs a STATIC vocabulary that still separates four reads.\n\n   Solution: static FORM — the one channel that is neither motion nor hue.\n       resting      hollow          ring only, transparent centre  (lightest)\n       working      solid           filled circle\n       needsYou     solid + halo    filled, plus a static ring at 1.9x\n       unavailable  solid + strike  filled, with a bar knocked through\n\n   Four distinct silhouettes at 16px that survive greyscale, ordered by visual\n   weight so the motion version's urgency ranking is preserved.\n\n   Acceptance test: render all four at 16px, greyscale, animation disabled.\n   If any two are confusable, this fallback has failed. */\n\n@media (prefers-reduced-motion: reduce) {\n\n  /* Hold every rig motion at its rest pose. */\n  .mav .mav-rig { animation: none !important; transform: none !important; }\n\n  /* Tip holds at FULL opacity, not its dimmest frame. */\n  .mav .mav-tip { animation: none !important; opacity: 1 !important; }\n\n  /* Fallback chatter stops and rests closed. Phoneme-driven mouth swaps are\n     NOT animation — they are discrete state changes carrying information, and\n     they keep running. Offer a separate app-level setting for users who want\n     lip-sync off too. */\n  .mav .mav-talk { animation: none !important; transform: none !important; }\n  .mav[data-state=\"speaking\"]:not([data-visemes]) .mav-mouth > .mouth-shape[data-shape=\"talk\"] { display: none !important; }\n  .mav[data-state=\"speaking\"]:not([data-visemes]) .mav-mouth:not([data-shape]) > .mouth-shape[data-shape=\"closed\"] { display: block; }\n\n  /* Accessories stop moving but stay VISIBLE — each one is a state's\n     differentiator, so hiding it would cost a read. */\n  .mav .mav-dots .acc-dot { animation: none !important; opacity: 1 !important; transform: none !important; }\n  .mav .mav-rings ellipse { animation: none !important; opacity: 0.85 !important; transform: none !important; }\n  .mav .mav-aperture { animation: none !important; opacity: 0.9 !important; transform: none !important; }\n  /* ingest holds at its mid-draw frame so the state still reads. */\n  .mav .mav-doc { animation: none !important; opacity: 1 !important; transform: translateY(-2px) scale(0.42) !important; }\n  /* The scan line is the exception: a static line across the face reads as\n     damage rather than scanning, so it is hidden outright. */\n  .mav .mav-scan { animation: none !important; display: none !important; }\n\n  /* --- tray: the structural case --- */\n  .tray-dot { animation: none !important; opacity: 1 !important; }\n  .tray-dot::after { animation: none !important; }\n\n  .tray-dot[data-read=\"resting\"] {\n    background: transparent;\n    box-shadow: inset 0 0 0 2px var(--tray-colour, #3f7fc4);\n  }\n  .tray-dot[data-read=\"working\"] {\n    background: var(--tray-colour, #3f7fc4);\n  }\n  .tray-dot[data-read=\"needsYou\"]::after {\n    inset: calc(var(--tray-size, 16px) * -0.45);\n    border: 1.5px solid var(--tray-colour, #3f7fc4);\n    transform: none;\n    opacity: 1;\n  }\n  .tray-dot[data-read=\"unavailable\"] {\n    background: var(--tray-colour, #f08a80);\n  }\n  .tray-dot[data-read=\"unavailable\"]::after {\n    inset: auto;\n    top: 50%;\n    left: 20%;\n    width: 60%;\n    height: 2px;\n    border-radius: 1px;\n    transform: translateY(-50%);\n    background: var(--tray-ground, #1d1f20);\n  }\n}\n";
